import { useCallback, useEffect, useState } from "react";
import api from "../../api/api";
import defaultSchoolLogo from "../../assets/dar-e-arqam-logo.svg";
import "./SchoolFinance.css";

const today = () => new Date().toISOString().slice(0, 10);
const monthNow = () => new Date().toISOString().slice(0, 7);
const yearStart = () => `${new Date().getFullYear()}-01-01`;
const money = (value) => `PKR ${Number(value || 0).toLocaleString("en-PK", { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
const errorText = (error, fallback = "The finance request could not be completed.") => error?.response?.data?.detail || error?.message || fallback;
const statusClass = (value) => String(value || "unknown").toLowerCase().replaceAll(" ", "-");
const emptyHead = { campus_id: null, name: "", code: "", category: "Tuition", description: "", is_refundable: true, is_active: true };
const emptyStructure = { campus_id: "", school_class_id: "", student_id: "", scope: "Campus", name: "", billing_frequency: "Monthly", billing_month: 4, due_day: 10, effective_from: "", effective_to: "", is_active: true, amounts: {} };
const emptyDiscount = { campus_id: "", student_id: "", fee_head_id: "", discount_type: "Sibling", name: "", calculation_type: "Percentage", value: "", start_date: "", end_date: "", notes: "", is_active: true };
const emptyGenerate = { campus_id: "", academic_session_id: "", billing_period: monthNow(), issue_date: today(), due_date: "", school_class_id: "", student_id: "", notes: "" };
const emptyPayment = { campus_id: "", student_id: "", finance_account_id: "", invoice_id: "", amount: "", payment_method: "Cash", payment_reference: "", received_date: today(), notes: "" };
const emptyAccount = { campus_id: "", name: "", account_type: "Cash", bank_name: "", account_number: "", opening_balance: 0, erp_accounting_account_id: "", is_active: true };
const emptyEntry = { campus_id: "", finance_account_id: "", target_account_id: "", direction: "Out", entry_type: "Expense", category: "General", amount: "", entry_date: today(), counterparty: "", reference: "", description: "" };

function SchoolFinance({ settings, permissions }) {
  const [tab, setTab] = useState("overview");
  const [campusId, setCampusId] = useState("");
  const [snapshot, setSnapshot] = useState({ summary: {}, fee_heads: [], structures: [], discounts: [], invoices: [], payments: [], accounts: [], closings: [], reconciliations: [], reminders: [], settings: {}, erp_accounts: [] });
  const [foundation, setFoundation] = useState({ campuses: [], sessions: [], classes: [] });
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState(null);
  const [headForm, setHeadForm] = useState(emptyHead);
  const [structureForm, setStructureForm] = useState(emptyStructure);
  const [discountForm, setDiscountForm] = useState(emptyDiscount);
  const [generateForm, setGenerateForm] = useState(emptyGenerate);
  const [paymentForm, setPaymentForm] = useState(emptyPayment);
  const [accountForm, setAccountForm] = useState(emptyAccount);
  const [entryForm, setEntryForm] = useState(emptyEntry);
  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [adjustmentForm, setAdjustmentForm] = useState({ adjustment_type: "Credit", category: "Custom", amount: "", reason: "" });
  const [refundPayment, setRefundPayment] = useState(null);
  const [refundForm, setRefundForm] = useState({ invoice_id: "", finance_account_id: "", amount: "", refund_method: "Cash", refund_date: today(), reason: "" });
  const [ledgerStudentId, setLedgerStudentId] = useState("");
  const [ledger, setLedger] = useState(null);
  const [closingForm, setClosingForm] = useState({ finance_account_id: "", closing_date: today(), actual_cash: "", notes: "" });
  const [reconcileForm, setReconcileForm] = useState({ finance_account_id: "", statement_date: today(), statement_balance: "", notes: "" });
  const [reportFilters, setReportFilters] = useState({ date_from: yearStart(), date_to: today(), school_class_id: "" });
  const [report, setReport] = useState({ statement: {}, accounts: [], defaulters: [], collections_by_date: [], entries: [] });
  const [policyForm, setPolicyForm] = useState({ invoice_prefix: "FEE", receipt_prefix: "RCP", default_due_day: 10, late_fee_type: "Flat", late_fee_value: 0, late_fee_grace_days: 0, automatic_reminders: true, reminder_days_before: 3, sync_to_erp: false });
  const logo = settings?.logo_data_url || defaultSchoolLogo;
  const canManage = permissions ? permissions.includes("manage_finance") : true;

  const loadBase = useCallback(async () => {
    setLoading(true);
    try {
      const params = campusId ? { campus_id: Number(campusId) } : {};
      const [financeResponse, foundationResponse, studentResponse] = await Promise.all([
        api.get("/school/finance", { params }),
        api.get("/school/foundation"),
        api.get("/school/student-information"),
      ]);
      const finance = financeResponse.data || {};
      const school = foundationResponse.data || {};
      const firstCampus = campusId || String(school.campuses?.[0]?.id || "");
      const currentSession = school.sessions?.find((item) => item.is_current && (!item.campus_id || item.campus_id === Number(firstCampus))) || school.sessions?.[0];
      setSnapshot(finance);
      setFoundation({ campuses: school.campuses || [], sessions: school.sessions || [], classes: school.classes || [] });
      setStudents(studentResponse.data || []);
      setStructureForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus) }));
      setDiscountForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus) }));
      setGenerateForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus), academic_session_id: current.academic_session_id || currentSession?.id || "" }));
      setPaymentForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus), finance_account_id: current.finance_account_id || finance.accounts?.[0]?.id || "" }));
      setAccountForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus) }));
      setEntryForm((current) => ({ ...current, campus_id: current.campus_id || Number(firstCampus), finance_account_id: current.finance_account_id || finance.accounts?.[0]?.id || "" }));
      setClosingForm((current) => ({ ...current, finance_account_id: current.finance_account_id || finance.accounts?.find((item) => item.account_type === "Cash")?.id || "" }));
      setReconcileForm((current) => ({ ...current, finance_account_id: current.finance_account_id || finance.accounts?.find((item) => item.account_type !== "Cash")?.id || finance.accounts?.[0]?.id || "" }));
      setPolicyForm({
        invoice_prefix: finance.settings?.invoice_prefix || "FEE", receipt_prefix: finance.settings?.receipt_prefix || "RCP",
        default_due_day: finance.settings?.default_due_day ?? 10, late_fee_type: finance.settings?.late_fee_type || "Flat",
        late_fee_value: finance.settings?.late_fee_value ?? 0, late_fee_grace_days: finance.settings?.late_fee_grace_days ?? 0,
        automatic_reminders: finance.settings?.automatic_reminders !== false, reminder_days_before: finance.settings?.reminder_days_before ?? 3,
        sync_to_erp: finance.settings?.sync_to_erp === true,
      });
      if (!campusId && firstCampus) setCampusId(firstCampus);
    } catch (error) {
      setNotice({ type: "error", text: errorText(error, "School finance could not be loaded.") });
    } finally { setLoading(false); }
  }, [campusId]);

  useEffect(() => { const timer = window.setTimeout(loadBase, 0); return () => window.clearTimeout(timer); }, [loadBase]);

  const campusStudents = students.filter((student) => student.campus_id === Number(campusId) && student.status === "Active");
  const campusClasses = foundation.classes.filter((item) => item.campus_id === Number(campusId));
  const studentInvoices = snapshot.invoices.filter((invoice) => !paymentForm.student_id || invoice.student_id === Number(paymentForm.student_id));
  const cashAccounts = snapshot.accounts.filter((account) => account.account_type === "Cash" && account.is_active);
  const selectedPaymentInvoices = refundPayment?.allocations || [];

  const run = async (action, success) => {
    setBusy(true); setNotice(null);
    try { const result = await action(); await loadBase(); setNotice({ type: "success", text: success }); return result; }
    catch (error) { setNotice({ type: "error", text: errorText(error) }); return null; }
    finally { setBusy(false); }
  };

  const createHead = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/fee-heads", { ...headForm, campus_id: headForm.campus_id || null }), "Fee head created.");
    if (result) setHeadForm(emptyHead);
  };

  const createStructure = async (event) => {
    event.preventDefault();
    const items = snapshot.fee_heads.map((head) => ({ fee_head_id: head.id, amount: Number(structureForm.amounts[head.id] || 0) })).filter((item) => item.amount > 0);
    if (!items.length) { setNotice({ type: "error", text: "Enter an amount for at least one fee head." }); return; }
    const payload = {
      ...structureForm, campus_id: Number(campusId), school_class_id: structureForm.scope === "Class" ? Number(structureForm.school_class_id) : null,
      student_id: structureForm.scope === "Student" ? Number(structureForm.student_id) : null, due_day: Number(structureForm.due_day), billing_month: Number(structureForm.billing_month),
      effective_from: structureForm.effective_from || null, effective_to: structureForm.effective_to || null, items,
    };
    delete payload.scope; delete payload.amounts;
    const result = await run(() => api.post("/school/finance/structures", payload), "Fee structure created.");
    if (result) setStructureForm({ ...emptyStructure, campus_id: Number(campusId) });
  };

  const createDiscount = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/discounts", { ...discountForm, campus_id: Number(campusId), student_id: Number(discountForm.student_id), fee_head_id: discountForm.fee_head_id ? Number(discountForm.fee_head_id) : null, value: Number(discountForm.value), start_date: discountForm.start_date || null, end_date: discountForm.end_date || null }), "Student discount added.");
    if (result) setDiscountForm({ ...emptyDiscount, campus_id: Number(campusId) });
  };

  const generateInvoices = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/invoices/generate", { ...generateForm, campus_id: Number(campusId), academic_session_id: generateForm.academic_session_id ? Number(generateForm.academic_session_id) : null, school_class_id: generateForm.school_class_id ? Number(generateForm.school_class_id) : null, student_id: generateForm.student_id ? Number(generateForm.student_id) : null, due_date: generateForm.due_date || null }), "Invoice generation completed.");
    if (result) setNotice({ type: "success", text: `${result.data.count} invoice${result.data.count === 1 ? "" : "s"} generated; ${result.data.skipped.length} skipped.` });
  };

  const recordPayment = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/payments", { ...paymentForm, campus_id: Number(campusId), student_id: Number(paymentForm.student_id), finance_account_id: Number(paymentForm.finance_account_id), invoice_id: paymentForm.invoice_id ? Number(paymentForm.invoice_id) : null, amount: Number(paymentForm.amount) }), "Payment posted and receipt created.");
    if (result) { setPaymentForm({ ...emptyPayment, campus_id: Number(campusId), finance_account_id: paymentForm.finance_account_id }); await showReceipt(result.data.id); }
  };

  const showReceipt = async (paymentId) => {
    try {
      const response = await api.get(`/school/finance/payments/${paymentId}/receipt`);
      const receipt = response.data;
      const receiptWindow = window.open("", "_blank", "width=760,height=780");
      if (!receiptWindow) { setNotice({ type: "error", text: "Allow pop-ups to print the receipt." }); return; }
      const allocations = receipt.allocations?.map((item) => `<li>${item.invoice_no}: ${money(item.amount)}</li>`).join("") || "<li>Advance fee</li>";
      receiptWindow.document.write(`<!doctype html><html><head><title>${receipt.payment_no}</title><style>body{font-family:Arial;padding:42px;color:#17175f}header{text-align:center;border-bottom:3px solid #191797;padding-bottom:18px}h1{margin:0}.amount{font-size:30px;font-weight:800;color:#191797}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #ddd}button{padding:10px 18px;background:#191797;color:white;border:0;border-radius:8px;margin-top:22px}@media print{button{display:none}}</style></head><body><header><h1>${receipt.school_name}</h1><p>${receipt.campus_name}</p><h2>Fee receipt</h2></header><div class="row"><b>Receipt</b><span>${receipt.payment_no}</span></div><div class="row"><b>Student</b><span>${receipt.student_name} (${receipt.admission_no})</span></div><div class="row"><b>Date</b><span>${receipt.received_date}</span></div><div class="row"><b>Method</b><span>${receipt.payment_method}</span></div><p class="amount">${money(receipt.amount)}</p><h3>Allocated to</h3><ul>${allocations}</ul><p>Advance balance: ${money(receipt.unallocated_amount)}</p><button onclick="window.print()">Print receipt</button></body></html>`);
      receiptWindow.document.close();
    } catch (error) { setNotice({ type: "error", text: errorText(error, "Receipt could not be opened.") }); }
  };

  const shareReceipt = async (paymentId) => {
    try {
      const response = await api.get(`/school/finance/payments/${paymentId}/receipt`);
      window.open(`https://wa.me/?text=${encodeURIComponent(response.data.whatsapp_text)}`, "_blank", "noopener,noreferrer");
    } catch (error) { setNotice({ type: "error", text: errorText(error, "Receipt could not be prepared for WhatsApp.") }); }
  };

  const createAdjustment = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/adjustments", { invoice_id: selectedInvoice.id, ...adjustmentForm, amount: Number(adjustmentForm.amount) }), "Invoice adjustment applied.");
    if (result) { setSelectedInvoice(null); setAdjustmentForm({ adjustment_type: "Credit", category: "Custom", amount: "", reason: "" }); }
  };

  const createRefund = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/refunds", { payment_id: refundPayment.id, invoice_id: refundForm.invoice_id ? Number(refundForm.invoice_id) : null, finance_account_id: Number(refundForm.finance_account_id), amount: Number(refundForm.amount), refund_method: refundForm.refund_method, refund_date: refundForm.refund_date, reason: refundForm.reason }), "Fee refund posted.");
    if (result) { setRefundPayment(null); setRefundForm({ invoice_id: "", finance_account_id: "", amount: "", refund_method: "Cash", refund_date: today(), reason: "" }); }
  };

  const loadLedger = async (studentId = ledgerStudentId) => {
    if (!studentId) return;
    setBusy(true);
    try { const response = await api.get(`/school/finance/ledger/${studentId}`); setLedger(response.data); }
    catch (error) { setNotice({ type: "error", text: errorText(error) }); }
    finally { setBusy(false); }
  };

  const createAccount = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/accounts", { ...accountForm, campus_id: accountForm.campus_id ? Number(accountForm.campus_id) : null, opening_balance: Number(accountForm.opening_balance), erp_accounting_account_id: accountForm.erp_accounting_account_id ? Number(accountForm.erp_accounting_account_id) : null }), "School finance account created.");
    if (result) setAccountForm({ ...emptyAccount, campus_id: Number(campusId) });
  };

  const createEntry = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/entries", { ...entryForm, campus_id: Number(campusId), finance_account_id: Number(entryForm.finance_account_id), target_account_id: entryForm.entry_type === "Transfer" ? Number(entryForm.target_account_id) : null, amount: Number(entryForm.amount) }), `${entryForm.entry_type} entry posted.`);
    if (result) setEntryForm({ ...emptyEntry, campus_id: Number(campusId), finance_account_id: entryForm.finance_account_id });
  };

  const closeCash = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/cash-closings", { campus_id: Number(campusId), finance_account_id: Number(closingForm.finance_account_id), closing_date: closingForm.closing_date, actual_cash: Number(closingForm.actual_cash), notes: closingForm.notes }), "Daily cash collection closed.");
    if (result) setClosingForm((current) => ({ ...current, actual_cash: "", notes: "" }));
  };

  const reconcile = async (event) => {
    event.preventDefault();
    const result = await run(() => api.post("/school/finance/reconciliations", { campus_id: Number(campusId), finance_account_id: Number(reconcileForm.finance_account_id), statement_date: reconcileForm.statement_date, statement_balance: Number(reconcileForm.statement_balance), notes: reconcileForm.notes }), "Account reconciliation saved.");
    if (result) setReconcileForm((current) => ({ ...current, statement_balance: "", notes: "" }));
  };

  const savePolicy = async (event) => {
    event.preventDefault();
    await run(() => api.put("/school/finance/settings", { ...policyForm, campus_id: Number(campusId), default_due_day: Number(policyForm.default_due_day), late_fee_value: Number(policyForm.late_fee_value), late_fee_grace_days: Number(policyForm.late_fee_grace_days), reminder_days_before: Number(policyForm.reminder_days_before) }), "Fee policy saved.");
  };

  const applyLateFees = () => run(() => api.post(`/school/finance/late-fees/apply?campus_id=${campusId}&as_of=${today()}`), "Late fees calculated for overdue invoices.");
  const sendReminders = () => run(() => api.post(`/school/finance/reminders/send?campus_id=${campusId}&as_of=${today()}`), "Outstanding balance reminders created.");

  const loadReports = async (event) => {
    event?.preventDefault(); setBusy(true);
    try {
      const response = await api.get("/school/finance/reports", { params: { campus_id: Number(campusId), date_from: reportFilters.date_from, date_to: reportFilters.date_to, ...(reportFilters.school_class_id ? { school_class_id: Number(reportFilters.school_class_id) } : {}) } });
      setReport(response.data);
    } catch (error) { setNotice({ type: "error", text: errorText(error) }); }
    finally { setBusy(false); }
  };

  const printDefaulters = () => {
    const popup = window.open("", "_blank", "width=900,height=760");
    if (!popup) return;
    const rows = report.defaulters.map((item) => `<tr><td>${item.student_name}<br><small>${item.admission_no}</small></td><td>${item.class_name} ${item.section || ""}</td><td>${item.invoice_no}</td><td>${item.due_date}</td><td>${money(item.balance)}</td></tr>`).join("");
    popup.document.write(`<!doctype html><html><head><title>Fee defaulters</title><style>body{font-family:Arial;padding:30px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border:1px solid #bbb;text-align:left}h1{color:#191797}@media print{button{display:none}}</style></head><body><h1>Fee defaulter report</h1><p>${report.date_from} to ${report.date_to}</p><table><thead><tr><th>Student</th><th>Class</th><th>Invoice</th><th>Due date</th><th>Balance</th></tr></thead><tbody>${rows}</tbody></table><button onclick="window.print()">Print</button></body></html>`);
    popup.document.close();
  };

  if (loading && !snapshot.fee_heads.length) return <div className="school-finance-loading"><img src={logo} alt="" /><span>Opening school finance…</span></div>;

  return (
    <div className="school-finance-page">
      <header className="sf-hero">
        <div className="sf-brand"><img src={logo} alt="Dar-e-Arqam" /><div><span className="sf-eyebrow">Separate school books · PKR</span><h1>Fees &amp; school accounting</h1><p>Billing, collections, ledgers, expenses and financial control in one workspace.</p></div></div>
        <label className="sf-campus-picker"><span>Campus</span><select value={campusId} onChange={(event) => setCampusId(event.target.value)}>{foundation.campuses.map((campus) => <option key={campus.id} value={campus.id}>{campus.name}</option>)}</select></label>
      </header>

      {notice && <div className={`sf-notice ${notice.type}`} role="status"><span>{notice.text}</span><button type="button" onClick={() => setNotice(null)}>×</button></div>}

      <nav className="sf-tabs" aria-label="School finance sections">
        {[["overview", "Overview"], ["setup", "Fee setup"], ["billing", "Billing"], ["payments", "Payments"], ["ledger", "Student ledger"], ["books", "School books"], ["reports", "Reports"]].map(([key, label]) => <button type="button" key={key} className={tab === key ? "active" : ""} onClick={() => setTab(key)}>{label}</button>)}
      </nav>

      {tab === "overview" && <div className="sf-stack">
        <section className="sf-metrics">
          {[{ label: "Total billed", value: snapshot.summary.billed, tone: "blue" }, { label: "Collected", value: snapshot.summary.collected, tone: "green" }, { label: "Outstanding", value: snapshot.summary.outstanding, tone: "red" }, { label: "Advance balance", value: snapshot.summary.advance, tone: "gold" }].map((item) => <article className={`sf-metric ${item.tone}`} key={item.label}><span>{item.label}</span><strong>{money(item.value)}</strong></article>)}
        </section>
        <section className="sf-grid two">
          <article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Collection desk</span><h2>Today’s position</h2></div></div><div className="sf-snapshot-list"><div><span>Collected today</span><strong>{money(snapshot.summary.today_collection)}</strong></div><div><span>Overdue invoices</span><strong>{snapshot.summary.overdue_invoices || 0}</strong></div><div><span>Active structures</span><strong>{snapshot.structures.filter((item) => item.is_active).length}</strong></div><div><span>Reminders prepared</span><strong>{snapshot.reminders.length}</strong></div></div>{canManage && <div className="sf-inline-actions"><button className="sf-button secondary" type="button" onClick={applyLateFees} disabled={busy}>Calculate late fees</button><button className="sf-button primary" type="button" onClick={sendReminders} disabled={busy}>Send reminders</button></div>}</article>
          <article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Accounts</span><h2>School book balances</h2></div><span className="sf-pill">Separate from factory</span></div><div className="sf-account-list">{snapshot.accounts.map((account) => <div key={account.id}><span><b>{account.name}</b><small>{account.account_type}{account.erp_account_name ? ` · Linked to ${account.erp_account_name}` : ""}</small></span><strong>{money(account.balance)}</strong></div>)}</div></article>
        </section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Recent activity</span><h2>Latest invoices and receipts</h2></div></div><div className="sf-table-wrap"><table><thead><tr><th>Reference</th><th>Student</th><th>Date / due</th><th>Status</th><th>Amount</th></tr></thead><tbody>{snapshot.invoices.slice(0, 8).map((invoice) => <tr key={`i-${invoice.id}`}><td><b>{invoice.invoice_no}</b><small>{invoice.billing_period}</small></td><td>{invoice.student_name}<small>{invoice.admission_no}</small></td><td>{invoice.issue_date}<small>Due {invoice.due_date}</small></td><td><span className={`sf-status ${statusClass(invoice.status)}`}>{invoice.status}</span></td><td><b>{money(invoice.total_amount)}</b><small>{money(invoice.balance_amount)} due</small></td></tr>)}{!snapshot.invoices.length && <tr><td colSpan="5" className="sf-empty">No fee invoices yet. Add a structure and generate your first billing month.</td></tr>}</tbody></table></div></section>
      </div>}

      {tab === "setup" && <div className="sf-stack">
        <section className="sf-grid two">
          <article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Configurable fees</span><h2>Add fee head</h2></div></div><form className="sf-form" onSubmit={createHead}><div className="sf-form-grid"><label><span>Name</span><input required value={headForm.name} onChange={(e) => setHeadForm({ ...headForm, name: e.target.value })} placeholder="Tuition fee" /></label><label><span>Code</span><input required value={headForm.code} onChange={(e) => setHeadForm({ ...headForm, code: e.target.value.toUpperCase() })} placeholder="TUITION" /></label><label><span>Category</span><select value={headForm.category} onChange={(e) => setHeadForm({ ...headForm, category: e.target.value })}>{["Tuition", "Admission", "Transport", "Examination", "Other"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="sf-check"><input type="checkbox" checked={headForm.is_refundable} onChange={(e) => setHeadForm({ ...headForm, is_refundable: e.target.checked })} /><span>Refundable when approved</span></label></div><label><span>Description</span><textarea value={headForm.description} onChange={(e) => setHeadForm({ ...headForm, description: e.target.value })} /></label><button className="sf-button primary" disabled={busy || !canManage}>Create fee head</button></form></article>
          <article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Fee catalogue</span><h2>Active fee heads</h2></div></div><div className="sf-chip-list">{snapshot.fee_heads.map((head) => <span key={head.id}><b>{head.name}</b><small>{head.code} · {head.category}</small></span>)}</div></article>
        </section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Campus → class → student</span><h2>Create fee structure</h2></div><span className="sf-pill">Most specific fee wins</span></div><form className="sf-form" onSubmit={createStructure}><div className="sf-form-grid four"><label><span>Structure name</span><input required value={structureForm.name} onChange={(e) => setStructureForm({ ...structureForm, name: e.target.value })} placeholder="Class 5 monthly fees" /></label><label><span>Applies to</span><select value={structureForm.scope} onChange={(e) => setStructureForm({ ...structureForm, scope: e.target.value, school_class_id: "", student_id: "" })}><option>Campus</option><option>Class</option><option>Student</option></select></label>{structureForm.scope === "Class" && <label><span>Class</span><select required value={structureForm.school_class_id} onChange={(e) => setStructureForm({ ...structureForm, school_class_id: e.target.value })}><option value="">Select class</option>{campusClasses.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}{structureForm.scope === "Student" && <label><span>Student</span><select required value={structureForm.student_id} onChange={(e) => setStructureForm({ ...structureForm, student_id: e.target.value })}><option value="">Select student</option>{campusStudents.map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.admission_no}</option>)}</select></label>}<label><span>Frequency</span><select value={structureForm.billing_frequency} onChange={(e) => setStructureForm({ ...structureForm, billing_frequency: e.target.value })}>{["Monthly", "Quarterly", "Annual", "One-time"].map((value) => <option key={value}>{value}</option>)}</select></label><label><span>Cycle begins</span><select value={structureForm.billing_month} onChange={(e) => setStructureForm({ ...structureForm, billing_month: e.target.value })}>{["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"].map((label, index) => <option key={label} value={index + 1}>{label}</option>)}</select></label><label><span>Due day</span><input type="number" min="1" max="28" value={structureForm.due_day} onChange={(e) => setStructureForm({ ...structureForm, due_day: e.target.value })} /></label><label><span>Effective from</span><input type="date" value={structureForm.effective_from} onChange={(e) => setStructureForm({ ...structureForm, effective_from: e.target.value })} /></label><label><span>Effective to</span><input type="date" value={structureForm.effective_to} onChange={(e) => setStructureForm({ ...structureForm, effective_to: e.target.value })} /></label></div><div className="sf-fee-amounts">{snapshot.fee_heads.filter((head) => head.is_active).map((head) => <label key={head.id}><span>{head.name}<small>{head.category}</small></span><input type="number" min="0" step="0.01" value={structureForm.amounts[head.id] || ""} onChange={(e) => setStructureForm({ ...structureForm, amounts: { ...structureForm.amounts, [head.id]: e.target.value } })} placeholder="0" /></label>)}</div><button className="sf-button primary" disabled={busy || !canManage}>Save fee structure</button></form></section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Pricing rules</span><h2>Fee structures</h2></div></div><div className="sf-structure-grid">{snapshot.structures.map((item) => <article key={item.id}><div><span className="sf-pill">{item.scope}</span><span className={`sf-status ${item.is_active ? "paid" : "void"}`}>{item.is_active ? "Active" : "Paused"}</span></div><h3>{item.name}</h3><p>{item.class_name || item.student_name || "Entire campus"}</p><strong>{money(item.total)}</strong><small>{item.billing_frequency} · due day {item.due_day}</small><ul>{item.items.map((fee) => <li key={fee.id}><span>{fee.fee_head_name}</span><b>{money(fee.amount)}</b></li>)}</ul></article>)}</div></section>
        <section className="sf-grid two"><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Concessions</span><h2>Student discount</h2></div></div><form className="sf-form" onSubmit={createDiscount}><label><span>Student</span><select required value={discountForm.student_id} onChange={(e) => setDiscountForm({ ...discountForm, student_id: e.target.value })}><option value="">Select student</option>{campusStudents.map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.admission_no}</option>)}</select></label><div className="sf-form-grid"><label><span>Discount type</span><select value={discountForm.discount_type} onChange={(e) => setDiscountForm({ ...discountForm, discount_type: e.target.value })}>{["Sibling", "Staff child", "Scholarship", "Custom"].map((value) => <option key={value}>{value}</option>)}</select></label><label><span>Discount name</span><input required value={discountForm.name} onChange={(e) => setDiscountForm({ ...discountForm, name: e.target.value })} placeholder="Sibling concession" /></label><label><span>Apply to</span><select value={discountForm.fee_head_id} onChange={(e) => setDiscountForm({ ...discountForm, fee_head_id: e.target.value })}><option value="">All fee heads</option>{snapshot.fee_heads.map((head) => <option key={head.id} value={head.id}>{head.name}</option>)}</select></label><label><span>Calculation</span><select value={discountForm.calculation_type} onChange={(e) => setDiscountForm({ ...discountForm, calculation_type: e.target.value })}><option>Percentage</option><option>Fixed</option></select></label><label><span>{discountForm.calculation_type === "Percentage" ? "Percent" : "Amount (PKR)"}</span><input required type="number" min="0.01" step="0.01" value={discountForm.value} onChange={(e) => setDiscountForm({ ...discountForm, value: e.target.value })} /></label><label><span>Starts</span><input type="date" value={discountForm.start_date} onChange={(e) => setDiscountForm({ ...discountForm, start_date: e.target.value })} /></label><label><span>Ends</span><input type="date" value={discountForm.end_date} onChange={(e) => setDiscountForm({ ...discountForm, end_date: e.target.value })} /></label></div><button className="sf-button primary" disabled={busy || !canManage}>Add discount</button></form></article><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Active concessions</span><h2>Discount register</h2></div></div><div className="sf-discount-list">{snapshot.discounts.map((item) => <div key={item.id}><span><b>{item.student_name}</b><small>{item.discount_type} · {item.fee_head_name}</small></span><strong>{item.calculation_type === "Percentage" ? `${item.value}%` : money(item.value)}</strong></div>)}{!snapshot.discounts.length && <p className="sf-empty">No student discounts configured.</p>}</div></article></section>
      </div>}

      {tab === "billing" && <div className="sf-stack">
        <section className="sf-card sf-billing-banner"><div><span className="sf-kicker">Automatic billing run</span><h2>Generate invoices</h2><p>Recurring rules, student discounts, due dates and available advance balances are applied automatically.</p></div><form className="sf-form" onSubmit={generateInvoices}><div className="sf-form-grid four"><label><span>Billing period</span><input type="month" required value={generateForm.billing_period} onChange={(e) => setGenerateForm({ ...generateForm, billing_period: e.target.value })} /></label><label><span>Issue date</span><input type="date" required value={generateForm.issue_date} onChange={(e) => setGenerateForm({ ...generateForm, issue_date: e.target.value })} /></label><label><span>Custom due date</span><input type="date" value={generateForm.due_date} onChange={(e) => setGenerateForm({ ...generateForm, due_date: e.target.value })} /></label><label><span>Class (optional)</span><select value={generateForm.school_class_id} onChange={(e) => setGenerateForm({ ...generateForm, school_class_id: e.target.value, student_id: "" })}><option value="">All classes</option>{campusClasses.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Student (optional)</span><select value={generateForm.student_id} onChange={(e) => setGenerateForm({ ...generateForm, student_id: e.target.value })}><option value="">All students</option>{campusStudents.filter((item) => !generateForm.school_class_id || item.school_class_id === Number(generateForm.school_class_id)).map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.admission_no}</option>)}</select></label></div><button className="sf-button primary" disabled={busy || !canManage}>{busy ? "Generating…" : "Generate invoices"}</button></form></section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Receivables</span><h2>Student invoices</h2></div><div className="sf-inline-actions"><button className="sf-button secondary small" type="button" onClick={applyLateFees} disabled={busy || !canManage}>Apply late fees</button><button className="sf-button secondary small" type="button" onClick={sendReminders} disabled={busy || !canManage}>Send reminders</button></div></div><div className="sf-table-wrap"><table><thead><tr><th>Invoice</th><th>Student</th><th>Bill</th><th>Paid / balance</th><th>Status</th><th></th></tr></thead><tbody>{snapshot.invoices.map((invoice) => <tr key={invoice.id}><td><b>{invoice.invoice_no}</b><small>{invoice.billing_period} · due {invoice.due_date}</small></td><td>{invoice.student_name}<small>{invoice.class_name} {invoice.section}</small></td><td><b>{money(invoice.total_amount)}</b><small>{money(invoice.discount_amount)} discount · {money(invoice.late_fee_amount)} late</small></td><td>{money(invoice.paid_amount)}<small>{money(invoice.balance_amount)} outstanding</small></td><td><span className={`sf-status ${statusClass(invoice.status)}`}>{invoice.status}</span></td><td>{canManage && <button className="sf-link" type="button" onClick={() => setSelectedInvoice(invoice)}>Adjust</button>}</td></tr>)}</tbody></table></div></section>
      </div>}

      {tab === "payments" && <div className="sf-stack">
        <section className="sf-grid two"><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Cash · bank · online</span><h2>Record payment</h2></div></div><form className="sf-form" onSubmit={recordPayment}><label><span>Student</span><select required value={paymentForm.student_id} onChange={(e) => setPaymentForm({ ...paymentForm, student_id: e.target.value, invoice_id: "" })}><option value="">Select student</option>{campusStudents.map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.admission_no}</option>)}</select></label><div className="sf-form-grid"><label><span>Invoice allocation</span><select value={paymentForm.invoice_id} onChange={(e) => setPaymentForm({ ...paymentForm, invoice_id: e.target.value })}><option value="">Oldest dues, then advance</option>{studentInvoices.filter((item) => item.balance_amount > 0).map((item) => <option key={item.id} value={item.id}>{item.invoice_no} · {money(item.balance_amount)} due</option>)}</select></label><label><span>Amount</span><input required type="number" min="0.01" step="0.01" value={paymentForm.amount} onChange={(e) => setPaymentForm({ ...paymentForm, amount: e.target.value })} /></label><label><span>Method</span><select value={paymentForm.payment_method} onChange={(e) => setPaymentForm({ ...paymentForm, payment_method: e.target.value })}><option>Cash</option><option>Bank</option><option>Online</option></select></label><label><span>Receiving account</span><select required value={paymentForm.finance_account_id} onChange={(e) => setPaymentForm({ ...paymentForm, finance_account_id: e.target.value })}>{snapshot.accounts.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Date</span><input type="date" required value={paymentForm.received_date} onChange={(e) => setPaymentForm({ ...paymentForm, received_date: e.target.value })} /></label><label><span>Reference</span><input value={paymentForm.payment_reference} onChange={(e) => setPaymentForm({ ...paymentForm, payment_reference: e.target.value })} placeholder="Cheque / transaction ID" /></label></div><label><span>Notes</span><textarea value={paymentForm.notes} onChange={(e) => setPaymentForm({ ...paymentForm, notes: e.target.value })} /></label><button className="sf-button primary" disabled={busy || !canManage}>Post payment &amp; receipt</button></form></article><article className="sf-card sf-advance-card"><span className="sf-kicker">Automatic allocation</span><h2>Partial &amp; advance fees</h2><p>Partial payments reduce the selected or oldest invoice. Any remaining amount stays as student advance credit and is automatically used on the next invoice.</p><div className="sf-big-number">{money(snapshot.summary.advance)}</div><small>Total unallocated student advances</small></article></section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Receipt register</span><h2>Recent fee payments</h2></div></div><div className="sf-table-wrap"><table><thead><tr><th>Receipt</th><th>Student</th><th>Method / account</th><th>Allocated</th><th>Advance</th><th>Actions</th></tr></thead><tbody>{snapshot.payments.map((payment) => <tr key={payment.id}><td><b>{payment.payment_no}</b><small>{payment.received_date}</small></td><td>{payment.student_name}<small>{payment.admission_no}</small></td><td>{payment.payment_method}<small>{payment.account_name}</small></td><td><b>{money(payment.allocated_amount)}</b><small>{payment.allocations.map((item) => item.invoice_no).join(", ") || "No invoice"}</small></td><td>{money(payment.unallocated_amount)}</td><td><div className="sf-row-actions"><button className="sf-link" onClick={() => showReceipt(payment.id)} type="button">Print</button><button className="sf-link whatsapp" onClick={() => shareReceipt(payment.id)} type="button">WhatsApp</button>{canManage && <button className="sf-link danger" type="button" onClick={() => { setRefundPayment(payment); setRefundForm((current) => ({ ...current, finance_account_id: payment.finance_account_id, refund_method: payment.payment_method })); }}>Refund</button>}</div></td></tr>)}</tbody></table></div></section>
      </div>}

      {tab === "ledger" && <div className="sf-stack"><section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Complete account history</span><h2>Student fee ledger</h2></div></div><div className="sf-ledger-search"><select value={ledgerStudentId} onChange={(e) => { setLedgerStudentId(e.target.value); setLedger(null); }}><option value="">Select student</option>{campusStudents.map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.admission_no}</option>)}</select><button className="sf-button primary" type="button" onClick={() => loadLedger()} disabled={!ledgerStudentId || busy}>Open ledger</button></div></section>{ledger && <><section className="sf-metrics compact"><article className="sf-metric blue"><span>Student</span><strong>{ledger.student.student_name}</strong><small>{ledger.student.admission_no} · {ledger.student.class_name} {ledger.student.section}</small></article><article className="sf-metric red"><span>Account balance</span><strong>{money(ledger.balance)}</strong><small>Positive means outstanding</small></article><article className="sf-metric gold"><span>Advance available</span><strong>{money(ledger.advance)}</strong></article></section><section className="sf-card"><div className="sf-table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>{ledger.entries.map((entry, index) => <tr key={`${entry.reference}-${index}`}><td>{entry.date}</td><td>{entry.type}</td><td>{entry.reference}</td><td>{entry.description}</td><td>{entry.debit ? money(entry.debit) : "—"}</td><td>{entry.credit ? money(entry.credit) : "—"}</td><td><b>{money(entry.balance)}</b></td></tr>)}</tbody></table></div></section></>}</div>}

      {tab === "books" && <div className="sf-stack">
        <section className="sf-grid two"><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Cash, bank &amp; online</span><h2>Add school account</h2></div></div><form className="sf-form" onSubmit={createAccount}><div className="sf-form-grid"><label><span>Name</span><input required value={accountForm.name} onChange={(e) => setAccountForm({ ...accountForm, name: e.target.value })} placeholder="HBL school fees" /></label><label><span>Account type</span><select value={accountForm.account_type} onChange={(e) => setAccountForm({ ...accountForm, account_type: e.target.value })}><option>Cash</option><option>Bank</option><option>Online</option></select></label><label><span>Bank / provider</span><input value={accountForm.bank_name} onChange={(e) => setAccountForm({ ...accountForm, bank_name: e.target.value })} /></label><label><span>Account number</span><input value={accountForm.account_number} onChange={(e) => setAccountForm({ ...accountForm, account_number: e.target.value })} /></label><label><span>Opening balance</span><input type="number" step="0.01" value={accountForm.opening_balance} onChange={(e) => setAccountForm({ ...accountForm, opening_balance: e.target.value })} /></label><label><span>Existing ERP account link</span><select value={accountForm.erp_accounting_account_id} onChange={(e) => setAccountForm({ ...accountForm, erp_accounting_account_id: e.target.value })}><option value="">Keep separate only</option>{snapshot.erp_accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><button className="sf-button primary" disabled={busy || !canManage}>Create account</button></form></article><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Income · expense · transfer</span><h2>Post school book entry</h2></div></div><form className="sf-form" onSubmit={createEntry}><div className="sf-form-grid"><label><span>Entry type</span><select value={entryForm.entry_type} onChange={(e) => setEntryForm({ ...entryForm, entry_type: e.target.value, direction: e.target.value === "Income" ? "In" : "Out" })}><option>Expense</option><option>Income</option><option>Transfer</option></select></label><label><span>From / account</span><select required value={entryForm.finance_account_id} onChange={(e) => setEntryForm({ ...entryForm, finance_account_id: e.target.value })}>{snapshot.accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{entryForm.entry_type === "Transfer" && <label><span>To account</span><select required value={entryForm.target_account_id} onChange={(e) => setEntryForm({ ...entryForm, target_account_id: e.target.value })}><option value="">Select account</option>{snapshot.accounts.filter((item) => item.id !== Number(entryForm.finance_account_id)).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}<label><span>Category</span><input value={entryForm.category} onChange={(e) => setEntryForm({ ...entryForm, category: e.target.value })} /></label><label><span>Amount</span><input required type="number" min="0.01" step="0.01" value={entryForm.amount} onChange={(e) => setEntryForm({ ...entryForm, amount: e.target.value })} /></label><label><span>Date</span><input required type="date" value={entryForm.entry_date} onChange={(e) => setEntryForm({ ...entryForm, entry_date: e.target.value })} /></label><label><span>Counterparty</span><input value={entryForm.counterparty} onChange={(e) => setEntryForm({ ...entryForm, counterparty: e.target.value })} /></label><label><span>Reference</span><input value={entryForm.reference} onChange={(e) => setEntryForm({ ...entryForm, reference: e.target.value })} /></label></div><label><span>Description</span><textarea value={entryForm.description} onChange={(e) => setEntryForm({ ...entryForm, description: e.target.value })} /></label><button className="sf-button primary" disabled={busy || !canManage}>Post entry</button></form></article></section>
        <section className="sf-grid two"><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">End of day</span><h2>Daily cash closing</h2></div></div><form className="sf-form" onSubmit={closeCash}><label><span>Cash account</span><select required value={closingForm.finance_account_id} onChange={(e) => setClosingForm({ ...closingForm, finance_account_id: e.target.value })}><option value="">Select cash account</option>{cashAccounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="sf-form-grid"><label><span>Closing date</span><input type="date" required value={closingForm.closing_date} onChange={(e) => setClosingForm({ ...closingForm, closing_date: e.target.value })} /></label><label><span>Actual cash counted</span><input type="number" min="0" step="0.01" required value={closingForm.actual_cash} onChange={(e) => setClosingForm({ ...closingForm, actual_cash: e.target.value })} /></label></div><label><span>Closing note</span><textarea value={closingForm.notes} onChange={(e) => setClosingForm({ ...closingForm, notes: e.target.value })} /></label><button className="sf-button primary" disabled={busy || !canManage}>Close collection day</button></form><div className="sf-mini-history">{snapshot.closings.slice(0, 5).map((item) => <div key={item.id}><span>{item.closing_date}<small>Expected {money(item.expected_cash)}</small></span><strong className={Math.abs(item.variance) > 0.009 ? "negative" : "positive"}>{money(item.variance)} variance</strong></div>)}</div></article><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Bank control</span><h2>Reconciliation</h2></div></div><form className="sf-form" onSubmit={reconcile}><label><span>Account</span><select required value={reconcileForm.finance_account_id} onChange={(e) => setReconcileForm({ ...reconcileForm, finance_account_id: e.target.value })}>{snapshot.accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="sf-form-grid"><label><span>Statement date</span><input type="date" required value={reconcileForm.statement_date} onChange={(e) => setReconcileForm({ ...reconcileForm, statement_date: e.target.value })} /></label><label><span>Statement balance</span><input type="number" step="0.01" required value={reconcileForm.statement_balance} onChange={(e) => setReconcileForm({ ...reconcileForm, statement_balance: e.target.value })} /></label></div><label><span>Notes</span><textarea value={reconcileForm.notes} onChange={(e) => setReconcileForm({ ...reconcileForm, notes: e.target.value })} /></label><button className="sf-button primary" disabled={busy || !canManage}>Reconcile account</button></form><div className="sf-mini-history">{snapshot.reconciliations.slice(0, 5).map((item) => <div key={item.id}><span>{item.statement_date}<small>Book {money(item.book_balance)}</small></span><strong className={item.status === "Reconciled" ? "positive" : "negative"}>{item.status} · {money(item.difference)}</strong></div>)}</div></article></section>
        <section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Fee automation</span><h2>Finance policy &amp; ERP link</h2></div></div><form className="sf-form" onSubmit={savePolicy}><div className="sf-form-grid four"><label><span>Invoice prefix</span><input value={policyForm.invoice_prefix} onChange={(e) => setPolicyForm({ ...policyForm, invoice_prefix: e.target.value.toUpperCase() })} /></label><label><span>Receipt prefix</span><input value={policyForm.receipt_prefix} onChange={(e) => setPolicyForm({ ...policyForm, receipt_prefix: e.target.value.toUpperCase() })} /></label><label><span>Default due day</span><input type="number" min="1" max="28" value={policyForm.default_due_day} onChange={(e) => setPolicyForm({ ...policyForm, default_due_day: e.target.value })} /></label><label><span>Late fee method</span><select value={policyForm.late_fee_type} onChange={(e) => setPolicyForm({ ...policyForm, late_fee_type: e.target.value })}><option>Flat</option><option>Percentage</option></select></label><label><span>Late fee value</span><input type="number" min="0" step="0.01" value={policyForm.late_fee_value} onChange={(e) => setPolicyForm({ ...policyForm, late_fee_value: e.target.value })} /></label><label><span>Grace days</span><input type="number" min="0" value={policyForm.late_fee_grace_days} onChange={(e) => setPolicyForm({ ...policyForm, late_fee_grace_days: e.target.value })} /></label><label><span>Remind days before due</span><input type="number" min="0" value={policyForm.reminder_days_before} onChange={(e) => setPolicyForm({ ...policyForm, reminder_days_before: e.target.value })} /></label><label className="sf-check"><input type="checkbox" checked={policyForm.automatic_reminders} onChange={(e) => setPolicyForm({ ...policyForm, automatic_reminders: e.target.checked })} /><span>Automatic reminder workflow</span></label><label className="sf-check"><input type="checkbox" checked={policyForm.sync_to_erp} onChange={(e) => setPolicyForm({ ...policyForm, sync_to_erp: e.target.checked })} /><span>Post mapped entries to existing ERP accounting</span></label></div><p className="sf-help">School accounts remain independent. When sync is enabled, only accounts explicitly mapped above create matching entries in the existing ERP accounting book.</p><button className="sf-button primary" disabled={busy || !canManage}>Save finance policy</button></form></section>
      </div>}

      {tab === "reports" && <div className="sf-stack"><section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Statements &amp; defaulters</span><h2>Financial reports</h2></div></div><form className="sf-report-filter" onSubmit={loadReports}><label><span>From</span><input type="date" value={reportFilters.date_from} onChange={(e) => setReportFilters({ ...reportFilters, date_from: e.target.value })} /></label><label><span>To</span><input type="date" value={reportFilters.date_to} onChange={(e) => setReportFilters({ ...reportFilters, date_to: e.target.value })} /></label><label><span>Class</span><select value={reportFilters.school_class_id} onChange={(e) => setReportFilters({ ...reportFilters, school_class_id: e.target.value })}><option value="">All classes</option>{campusClasses.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><button className="sf-button primary" disabled={busy}>Run reports</button></form></section>{report.date_from && <><section className="sf-metrics report">{[["Fees billed", report.statement.fees_billed, "blue"], ["Fee collected", report.statement.fee_income_collected, "green"], ["Expenses", report.statement.expenses, "red"], ["Net cash flow", report.statement.net_cash_flow, "gold"], ["Outstanding", report.statement.outstanding, "red"]].map(([label, value, tone]) => <article className={`sf-metric ${tone}`} key={label}><span>{label}</span><strong>{money(value)}</strong></article>)}</section><section className="sf-grid two"><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Position</span><h2>Account balances</h2></div></div><div className="sf-account-list">{report.accounts.map((account) => <div key={account.id}><span><b>{account.name}</b><small>{account.account_type}</small></span><strong>{money(account.balance)}</strong></div>)}</div></article><article className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Cash flow</span><h2>Income statement</h2></div></div><div className="sf-snapshot-list"><div><span>Other income</span><strong>{money(report.statement.other_income)}</strong></div><div><span>Discounts allowed</span><strong>{money(report.statement.discounts)}</strong></div><div><span>Late fees billed</span><strong>{money(report.statement.late_fees)}</strong></div><div><span>Refunds paid</span><strong>{money(report.statement.refunds)}</strong></div></div></article></section><section className="sf-card"><div className="sf-card-head"><div><span className="sf-kicker">Class &amp; campus balances</span><h2>Fee defaulters</h2></div><button className="sf-button secondary small" type="button" onClick={printDefaulters}>Print report</button></div><div className="sf-table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Invoice</th><th>Due</th><th>Days overdue</th><th>Balance</th></tr></thead><tbody>{report.defaulters.map((item) => <tr key={item.invoice_id}><td><b>{item.student_name}</b><small>{item.admission_no}</small></td><td>{item.class_name} {item.section}</td><td>{item.invoice_no}</td><td>{item.due_date}</td><td>{item.days_overdue}</td><td><b>{money(item.balance)}</b></td></tr>)}{!report.defaulters.length && <tr><td colSpan="6" className="sf-empty">No outstanding balances in this report range.</td></tr>}</tbody></table></div></section></>}</div>}

      {selectedInvoice && <div className="sf-modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && setSelectedInvoice(null)}><form className="sf-modal" onSubmit={createAdjustment}><div className="sf-card-head"><div><span className="sf-kicker">{selectedInvoice.invoice_no}</span><h2>Fee adjustment</h2></div><button type="button" className="sf-modal-close" onClick={() => setSelectedInvoice(null)}>×</button></div><p>{selectedInvoice.student_name} · current balance {money(selectedInvoice.balance_amount)}</p><div className="sf-form-grid"><label><span>Adjustment</span><select value={adjustmentForm.adjustment_type} onChange={(e) => setAdjustmentForm({ ...adjustmentForm, adjustment_type: e.target.value })}><option>Credit</option><option>Debit</option></select></label><label><span>Category</span><input value={adjustmentForm.category} onChange={(e) => setAdjustmentForm({ ...adjustmentForm, category: e.target.value })} /></label><label><span>Amount</span><input required type="number" min="0.01" step="0.01" value={adjustmentForm.amount} onChange={(e) => setAdjustmentForm({ ...adjustmentForm, amount: e.target.value })} /></label></div><label><span>Reason</span><textarea required value={adjustmentForm.reason} onChange={(e) => setAdjustmentForm({ ...adjustmentForm, reason: e.target.value })} /></label><button className="sf-button primary" disabled={busy}>Apply adjustment</button></form></div>}

      {refundPayment && <div className="sf-modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && setRefundPayment(null)}><form className="sf-modal" onSubmit={createRefund}><div className="sf-card-head"><div><span className="sf-kicker">{refundPayment.payment_no}</span><h2>Process fee refund</h2></div><button type="button" className="sf-modal-close" onClick={() => setRefundPayment(null)}>×</button></div><p>{refundPayment.student_name} · original payment {money(refundPayment.amount)}</p><div className="sf-form-grid"><label><span>Refund from</span><select value={refundForm.invoice_id} onChange={(e) => setRefundForm({ ...refundForm, invoice_id: e.target.value })}><option value="">Advance balance ({money(refundPayment.unallocated_amount)})</option>{selectedPaymentInvoices.map((item) => <option key={item.id} value={item.invoice_id}>{item.invoice_no} · max {money(item.amount)}</option>)}</select></label><label><span>Refund account</span><select required value={refundForm.finance_account_id} onChange={(e) => setRefundForm({ ...refundForm, finance_account_id: e.target.value })}>{snapshot.accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Amount</span><input required type="number" min="0.01" step="0.01" value={refundForm.amount} onChange={(e) => setRefundForm({ ...refundForm, amount: e.target.value })} /></label><label><span>Date</span><input required type="date" value={refundForm.refund_date} onChange={(e) => setRefundForm({ ...refundForm, refund_date: e.target.value })} /></label></div><label><span>Reason</span><textarea required value={refundForm.reason} onChange={(e) => setRefundForm({ ...refundForm, reason: e.target.value })} /></label><button className="sf-button danger" disabled={busy}>Post refund</button></form></div>}
    </div>
  );
}

export default SchoolFinance;
